// Demo: Copy-on-Write Snapshots — snapshot verify by restore drill
function hash(s){var h=5381;for(var i=0;i<s.length;i++){h=((h<<5)+h+s.charCodeAt(i))>>>0;}return h.toString(16);}
var original='state-1-3';var snap=hash(original);var restored='state-1-3';
console.log('technique: Copy-on-Write Snapshots');console.log('snapshot hash: '+snap);
console.log(hash(restored)===snap?'restore drill: PASS — snapshot restores exactly':'restore drill: FAIL');

// Demo: Event Sourcing — event replay rebuild
var events=[];for(var i=0;i<9;i++){events.push({op:i%3===0?'add':'set',k:'k'+((i*7+2)%5),v:(i*13)%100});}
var state={};events.forEach(function(e){if(e.op==='add')state[e.k]=(state[e.k]||0)+e.v;else state[e.k]=e.v;});
console.log('technique: Event Sourcing');console.log('events replayed: '+events.length);
console.log('rebuilt state: '+JSON.stringify(state));

