// Demo: Incremental Snapshot Chains — snapshot chain storage math
var full=1000,deltas=[];for(var i=0;i<64;i++){deltas.push(40+((i*31+10)%60));}
var chain=deltas.reduce(function(a,b){return a+b;},0);
console.log('technique: Incremental Snapshot Chains');console.log('full snapshots: '+64+' x '+full+' MB = '+(full*64)+' MB');
console.log('chain: 1 full + '+(64-1)+' deltas = '+(full+chain-deltas[0])+' MB');
console.log('savings: '+(100*(1-(full+chain-deltas[0])/(full*64))).toFixed(0)+'% with incremental chains');

